theorem imo2022_p2 (f : ℝ+ → ℝ+) :
    f ∈ solution_set ↔
    ∀ x, ∃! y, x * f y + y * f x ≤ ⟨2, two_pos⟩   := by
  constructor;
  · intro hf;
    simp only [Set.mem_singleton_iff] at hf;
    rw [hf] at *; clear hf;
    intro x;
    use x;
    constructor;
    suffices h : (1:ℝ+) + 1 = ⟨2, two_pos⟩ by
